import React, { useState, useEffect } from 'react';
import SlideBarComponent from '../../components/SlideBar/SlideBarComponent';
import { PieChart, Pie, Cell, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { getAverageBenefitsByShareholder } from '../../service/statisticsservice';
import './BenefitSharehoder.scss';

const COLORS = ['#28a745', '#dc3545'];

const BenefitSharehoder = () => {
    const [data, setData] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchData = async () => {
            try {
                const response = await getAverageBenefitsByShareholder();
                const chartData = response.map(item => ({
                    name: item.Shareholder_Status === 'Shareholder' ? 'Cổ đông' :
                        item.Shareholder_Status === 'Non-Shareholder' ? 'Không là cổ đông' :
                            'Chưa xác định',
                    deductable: parseFloat(item.average_deductable),
                    copay: parseFloat(item.average_copay)
                })).sort((a, b) => a.name === 'Cổ đông' ? -1 : 1);

                setData(chartData);
            } catch (error) {
                console.error("Error fetching benefit data:", error);
            } finally {
                setLoading(false);
            }
        };

        fetchData();
    }, []);

    if (loading) {
        return (
            <div className='container'>
                <div className='sidebar'>
                    <SlideBarComponent />
                </div>
                <div className='content w-100 d-flex justify-content-center align-items-center'>
                    <div className="spinner-border text-primary" role="status">
                        <span className="visually-hidden">Đang tải...</span>
                    </div>
                </div>
            </div>
        );
    }

    const totalDeductable = data.reduce((sum, item) => sum + item.deductable, 0);
    const totalCopay = data.reduce((sum, item) => sum + item.copay, 0);

    return (
        <div className='container'>
            <div className='sidebar'>
                <SlideBarComponent />
            </div>
            <div className='content w-100'>
                <h3 className="mb-4">Thống Kê Phúc Lợi Theo Cổ Đông</h3>

                <div className="row">
                    <div className="col-md-12 mb-4">
                        <div className="card shadow-sm">
                            <div className="card-body">
                                <h5 className="card-title mb-4">Chi Tiết Phúc Lợi</h5>
                                <table className="table table-bordered table-hover">
                                    <thead className="table-dark">
                                        <tr>
                                            <th>Trạng thái</th>
                                            <th>Khấu trừ trung bình</th>
                                            <th>Tỷ lệ khấu trừ</th>
                                            <th>Đồng chi trả trung bình (%)</th>
                                            <th>Tỷ lệ đồng chi trả</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {data.map((item, index) => (
                                            <tr key={index}>
                                                <td>{item.name}</td>
                                                <td className="text-end">{new Intl.NumberFormat('vi-VN', {
                                                    style: 'currency',
                                                    currency: 'VND'
                                                }).format(item.deductable)}</td>
                                                <td className="text-end">
                                                    {((item.deductable / totalDeductable) * 100).toFixed(1)}%
                                                </td>
                                                <td className="text-end">{item.copay.toFixed(1)}%</td>
                                                <td className="text-end">
                                                    {((item.copay / totalCopay) * 100).toFixed(1)}%
                                                </td>
                                            </tr>
                                        ))}
                                        <tr className="table-info">
                                            <td><strong>Tổng cộng</strong></td>
                                            <td className="text-end"><strong>{new Intl.NumberFormat('vi-VN', {
                                                style: 'currency',
                                                currency: 'VND'
                                            }).format(totalDeductable)}</strong></td>
                                            <td className="text-end"><strong>100%</strong></td>
                                            <td className="text-end"><strong>{totalCopay.toFixed(1)}%</strong></td>
                                            <td className="text-end"><strong>100%</strong></td>
                                        </tr>
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    </div>

                    <div className="col-md-6">
                        <div className="card shadow-sm">
                            <div className="card-body" style={{ height: '400px' }}>
                                <h5 className="card-title mb-4">Biểu Đồ Khấu Trừ</h5>
                                <ResponsiveContainer width="100%" height="100%">
                                    <PieChart>
                                        <Pie
                                            data={data}
                                            cx="50%"
                                            cy="50%"
                                            outerRadius={130}
                                            dataKey="deductable"
                                            label={({ name, percent }) => `${name} (${(percent * 100).toFixed(1)}%)`}
                                            labelLine
                                        >
                                            {data.map((entry, index) => (
                                                <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                            ))}
                                        </Pie>
                                        <Tooltip
                                            formatter={(value) => new Intl.NumberFormat('vi-VN', {
                                                style: 'currency',
                                                currency: 'VND'
                                            }).format(value)}
                                        />
                                        <Legend />
                                    </PieChart>
                                </ResponsiveContainer>
                            </div>
                        </div>
                    </div>

                    <div className="col-md-6">
                        <div className="card shadow-sm">
                            <div className="card-body" style={{ height: '400px' }}>
                                <h5 className="card-title mb-4">Biểu Đồ Đồng Chi Trả</h5>
                                <ResponsiveContainer width="100%" height="100%">
                                    <PieChart>
                                        <Pie
                                            data={data}
                                            cx="50%"
                                            cy="50%"
                                            outerRadius={130}
                                            dataKey="copay"
                                            label={({ name, percent }) => `${name} (${(percent * 100).toFixed(1)}%)`}
                                            labelLine
                                        >
                                            {data.map((entry, index) => (
                                                <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                            ))}
                                        </Pie>
                                        <Tooltip formatter={(value) => `${value.toFixed(1)}%`} />
                                        <Legend />
                                    </PieChart>
                                </ResponsiveContainer>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default BenefitSharehoder;
